function i(o){try{let r=new Date(Number(o||Date.now())),t=r.getHours(),e=r.getMinutes(),n=t>=12?"PM":"AM";return t=t%12||12,`${t}:${String(e).padStart(2,"0")} ${n}`}catch{return""}}function s(o){if(!o)return"Never";let r=Date.now()-o;if(r<0)return new Date(o).toLocaleString();let t=Math.floor(r/1e3);if(t<60)return`${t}s ago`;let e=Math.floor(t/60);if(e<60)return`${e}m ago`;let n=Math.floor(e/60);if(n<24)return`${n}h ago`;let a=Math.floor(n/24);return a<7?`${a}d ago`:new Date(o).toLocaleDateString()}export{i as a,s as b};
